/* Signature Finnish Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Mattivirta": "From Matti + virta (stream).", "Maijamaki": "From Maija + maki (hill).", "Juhoniemi": "From Juho + niemi (cape).", "Ainoranta": "From Aino + ranta (shore).", "Vainojarvi": "From Vaino + jarvi (lake).", "Ilmarikuu": "From Ilmari + kuu (moon).", "Mattivirta-nen": "Signature surname in -nen style.", "Ainorantanen": "Signature surname in -nen style.", "Vainojarvinen": "Signature surname in -nen style.", "Ilmarikuunen": "Signature surname in -nen style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Mattivirta';
console.log(lookup(q));

